-- Seed Top 10 category clinics (Nahal #1 + samples)
-- Generated for scripts/seed-category-top10-docker.sh
BEGIN;
CREATE TABLE IF NOT EXISTS category_top_clinics (
  id TEXT PRIMARY KEY,
  category_id TEXT NOT NULL,
  clinic_id INTEGER NOT NULL,
  rank INTEGER NOT NULL,
  name TEXT,
  tagline TEXT,
  image TEXT,
  link TEXT,
  badge TEXT,
  active INTEGER NOT NULL DEFAULT 1,
  clicks INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_category_top_cat ON category_top_clinics (category_id, rank);
DELETE FROM category_top_clinics WHERE category_id = 'hair';
DELETE FROM category_top_clinics WHERE category_id = 'skin';
DELETE FROM category_top_clinics WHERE category_id = 'laser';
DELETE FROM category_top_clinics WHERE category_id = 'injection';
DELETE FROM category_top_clinics WHERE category_id = 'surgery';
DELETE FROM category_top_clinics WHERE category_id = 'slimming';
DELETE FROM category_top_clinics WHERE category_id = 'lasik';
DELETE FROM category_top_clinics WHERE category_id = 'femto-lasik';
DELETE FROM category_top_clinics WHERE category_id = 'prk';
COMMIT;
SELECT category_id, COUNT(*) AS n FROM category_top_clinics GROUP BY category_id ORDER BY category_id;
